class Ledger { final int? id; final String name, currencyCode; final bool isClosed; Ledger({this.id, required this.name, required this.currencyCode, this.isClosed=false}); Map<String,Object?> toMap()=>{'id':id,'name':name,'currency_code':currencyCode,'is_closed':isClosed?1:0}; factory Ledger.fromMap(Map<String,Object?> m)=>Ledger(id:m['id'] as int,name:m['name'] as String,currencyCode:m['currency_code'] as String,isClosed:(m['is_closed'] as int)==1); }
class Person { final int? id, ledgerId; final String name, phone, address, notes, kind; final String? photoPath; Person({this.id,required this.ledgerId,required this.name,this.phone='',this.address='',this.notes='',this.kind='person',this.photoPath}); Map<String,Object?> toMap()=>{'id':id,'ledger_id':ledgerId,'name':name,'phone':phone,'address':address,'notes':notes,'kind':kind,'photo_path':photoPath}; factory Person.fromMap(Map<String,Object?> m)=>Person(id:m['id'] as int,ledgerId:m['ledger_id'] as int,name:m['name'] as String,phone:(m['phone']??'') as String,address:(m['address']??'') as String,notes:(m['notes']??'') as String,kind:(m['kind']??'person') as String,photoPath:m['photo_path'] as String?); }
class TransactionItem { final int? id, ledgerId, personId; final String type, description, notes, category; final double amount; final DateTime date; TransactionItem({this.id,required this.ledgerId,required this.personId,required this.type,required this.amount,required this.date,this.description='',this.notes='',this.category=''}); Map<String,Object?> toMap()=>{'id':id,'ledger_id':ledgerId,'person_id':personId,'type':type,'amount':amount,'date':date.toIso8601String(),'description':description,'notes':notes,'category':category}; factory TransactionItem.fromMap(Map<String,Object?> m)=>TransactionItem(id:m['id'] as int,ledgerId:m['ledger_id'] as int,personId:m['person_id'] as int,type:m['type'] as String,amount:(m['amount'] as num).toDouble(),date:DateTime.parse(m['date'] as String),description:(m['description']??'') as String,notes:(m['notes']??'') as String,category:(m['category']??'') as String); }
